def replace_function(text, func_name, new_func):
    needle = "static xmlChar *\n" + func_name + "(htmlParserCtxtPtr ctxt)"
    start = text.find(needle)
    if start < 0:
        raise SystemExit(f'Could not find {func_name}')

    brace = text.find('{', start)
    if brace < 0:
        raise SystemExit(f'Could not find opening brace for {func_name}')

    i = brace
    depth = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                end = i + 1
                # consume trailing newlines
                while end < n and text[end] == '\n':
                    end += 1
                return text[:start] + new_func + "\n" + text[end:]
        i += 1

    raise SystemExit(f'Could not find end of {func_name}')

