import pathlib

html = pathlib.Path("HTMLparser.c")
src = html.read_text(encoding="utf-8", errors="surrogateescape")

sys_new = pathlib.Path("/tmp/htmlParseSystemLiteral.cfrag").read_text(encoding="utf-8")
pub_new = pathlib.Path("/tmp/htmlParsePubidLiteral.cfrag").read_text(encoding="utf-8")

def replace(text, func_name, new_body):
    needle = "static xmlChar *\n" + func_name + "(htmlParserCtxtPtr ctxt)"
    start = text.find(needle)
    if start < 0:
        raise SystemExit(f"missing {func_name}")
    brace = text.find("{", start)
    if brace < 0:
        raise SystemExit(f"missing brace {func_name}")
    i = brace
    depth = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                end = i + 1
                while end < n and text[end] == "\n":
                    end += 1
                return text[:start] + new_body + "\n" + text[end:]
        i += 1
    raise SystemExit(f"unterminated {func_name}")

src = replace(src, "htmlParseSystemLiteral", sys_new)
src = replace(src, "htmlParsePubidLiteral", pub_new)

html.write_text(src, encoding="utf-8", errors="surrogateescape")
print("ok")
