import pathlib

path = pathlib.Path("HTMLparser.c")
src = path.read_text(encoding="utf-8", errors="surrogateescape")

def replace_function(src_text, func_name, new_func):
    needle = "static xmlChar *\n" + func_name + "(htmlParserCtxtPtr ctxt)"
    start = src_text.find(needle)
    if start < 0:
        raise SystemExit("Could not find %s" % func_name)
    brace = src_text.find("{", start)
    if brace < 0:
        raise SystemExit("Could not find opening brace for %s" % func_name)
    i = brace
    depth = 0
    n = len(src_text)
    while i < n:
        c = src_text[i]
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                end = i + 1
                # consume trailing newlines
                while end < n and src_text[end] == "\n":
                    end += 1
                return src_text[:start] + new_func + "\n" + src_text[end:]
        i += 1
    raise SystemExit("Could not find end of %s" % func_name)

